local r=fu:GetResolve();local p=r:GetProjectManager():GetCurrentProject();print('PROJECT',p:GetName());for i=1,p:GetTimelineCount() do local t=p:GetTimelineByIndex(i);if string.find(t:GetName(),'v20') then print('TIMELINE',t:GetName(),t:GetEndFrame());for _,k in ipairs({'video','audio'}) do for _,c in ipairs(t:GetItemListInTrack(k,1)) do print('ITEM',k,c:GetName(),c:GetStart(),c:GetEnd());dump(c:GetSpeed());if k=='video' then dump(c:GetProperty()) end end end end end
